------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/

require("monitors")

---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
Terminal = "kitty"
FileManager = "nautilus"
Browser = "brave-browser"
Appmenu = "walker"

